<?php
require __DIR__.'/bootstrap.php';require_perm('settings.manage');
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();
    $values=['company_name'=>trim($_POST['company_name']),'company_tagline'=>trim($_POST['company_tagline']),'company_address'=>trim($_POST['company_address']??''),'company_mobile_numbers'=>trim($_POST['company_mobile_numbers']??''),'date_format'=>$_POST['date_format'],'timezone'=>$_POST['timezone'],'currency'=>strtoupper(trim($_POST['currency']??'USD')),'language'=>$_POST['language']??'en'];
    if($values['company_name']===''){$values['company_name']='CargoSom';}
    if(!in_array($values['date_format'],['d M Y','d/m/Y','m/d/Y','Y-m-d','d M Y H:i'],true))$values['date_format']='d M Y';
    if(!in_array($values['timezone'],timezone_identifiers_list(),true))$values['timezone']='Africa/Nairobi';
    if(!preg_match('/^[A-Z]{3}$/',$values['currency']))$values['currency']='USD';
    if(!in_array($values['language'],['en','so','ar'],true))$values['language']='en';
    if(isset($_FILES['logo'])&&$_FILES['logo']['error']!==UPLOAD_ERR_NO_FILE){
        if($_FILES['logo']['error']!==UPLOAD_ERR_OK||$_FILES['logo']['size']>2*1024*1024){flash('danger','Logo upload failed or exceeded the 2 MB limit.');redirect('settings.php');}
        $mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['logo']['tmp_name']);$types=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'];
        if(!isset($types[$mime])){flash('danger','Logo must be a PNG, JPG, or WebP image.');redirect('settings.php');}
        $dir=__DIR__.'/uploads/company';if(!is_dir($dir))mkdir($dir,0755,true);$filename='logo-'.bin2hex(random_bytes(8)).'.'.$types[$mime];
        if(!move_uploaded_file($_FILES['logo']['tmp_name'],$dir.'/'.$filename)){flash('danger','The logo could not be saved.');redirect('settings.php');}$values['logo_path']='uploads/company/'.$filename;
    }
    $stmt=$pdo->prepare('INSERT INTO company_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach($values as $key=>$value)$stmt->execute([$key,$value]);flash('success','Company settings updated.');redirect('settings.php');
}
$title='Settings';require __DIR__.'/partials/header.php';?>
<div class="mb-4"><h1 class="h3 fw-bold mb-1">Company settings</h1><p class="text-secondary mb-0">Configure company identity and how dates appear throughout the system.</p></div><div class="row g-4"><div class="col-lg-8"><form method="post" enctype="multipart/form-data" class="card p-4"><input type="hidden" name="csrf" value="<?=csrf()?>"><h2 class="h5 mb-4">Company profile</h2><div class="row g-3"><div class="col-md-6"><label class="form-label">Company name</label><input class="form-control" name="company_name" value="<?=e(setting('company_name','CargoSom'))?>" required></div><div class="col-md-6"><label class="form-label">Company tagline</label><input class="form-control" name="company_tagline" value="<?=e(setting('company_tagline','Cargo Agency'))?>"></div><div class="col-12"><label class="form-label">Company logo</label><input class="form-control" type="file" name="logo" accept="image/png,image/jpeg,image/webp"><div class="form-text">PNG, JPG, or WebP. Maximum 2 MB. A square or horizontal transparent logo works best.</div></div></div><hr class="my-4"><h2 class="h5 mb-4">Date and time</h2><div class="row g-3"><div class="col-md-6"><label class="form-label">Date format</label><select class="form-select" name="date_format"><?php foreach(['d M Y'=>'05 Aug 2026','d/m/Y'=>'05/08/2026','m/d/Y'=>'08/05/2026','Y-m-d'=>'2026-08-05','d M Y H:i'=>'05 Aug 2026 14:30'] as $key=>$label):?><option value="<?=e($key)?>" <?=setting('date_format','d M Y')===$key?'selected':''?>><?=e($label)?></option><?php endforeach?></select></div><div class="col-md-6"><label class="form-label">Time zone</label><select class="form-select" name="timezone"><?php foreach(['Africa/Nairobi','Africa/Mogadishu','Asia/Dubai','UTC'] as $zone):?><option <?=setting('timezone','Africa/Nairobi')===$zone?'selected':''?>><?=e($zone)?></option><?php endforeach?></select></div></div><hr class="my-4"><h2 class="h5 mb-4">Currency and language</h2><div class="row g-3"><div class="col-md-6"><label class="form-label">Currency (3-letter code)</label><select class="form-select" name="currency"><?php foreach(['USD'=>'USD · US Dollar','EUR'=>'EUR · Euro','GBP'=>'GBP · British Pound','KES'=>'KES · Kenyan Shilling','SOS'=>'SOS · Somali Shilling','AED'=>'AED · UAE Dirham','SAR'=>'SAR · Saudi Riyal','QAR'=>'QAR · Qatari Riyal','KWD'=>'KWD · Kuwaiti Dinar'] as $key=>$label):?><option value="<?=e($key)?>" <?=setting('currency','USD')===$key?'selected':''?>><?=e($label)?></option><?php endforeach?></select><div class="form-text">Shown before every amount in the system.</div></div><div class="col-md-6"><label class="form-label">Language</label><select class="form-select" name="language"><?php foreach(['en'=>'English','so'=>'Soomaali (Somali)','ar'=>'العربية (Arabic)'] as $key=>$label):?><option value="<?=e($key)?>" <?=setting('language','en')===$key?'selected':''?>><?=e($label)?></option><?php endforeach?></select><div class="form-text">Applies to sidebar and navigation labels.</div></div></div><div class="mt-4"><button class="btn btn-primary px-4">Save settings</button></div></form></div><div class="col-lg-4"><div class="card p-4 text-center"><h2 class="h6 text-secondary">Brand preview</h2><?php if(setting('logo_path')):?><img src="<?=url(setting('logo_path'))?>" class="settings-logo mx-auto my-3" alt="Company logo"><?php else:?><div class="settings-logo-placeholder mx-auto my-3"><?=e(strtoupper(substr(setting('company_name','CargoSom'),0,2)))?></div><?php endif?><h3 class="h4 mb-1"><?=e(setting('company_name','CargoSom'))?></h3><p class="text-secondary"><?=e(setting('company_tagline','Cargo Agency'))?></p><hr><small class="text-secondary">Date preview</small><strong><?=e(app_date())?></strong></div></div></div>
<?php require __DIR__.'/partials/footer.php';?>
